import math

def fatigue_life(Sa, Sm, Sut, Se):
    Sar = Sa / (1 - Sm / Sut) if Sm > 0 else Sa
    if Sar <= Se:
        return math.inf
    b = -math.log10(0.9 * Sut / Se) / 3
    a = 0.9 * Sut / 1e3 ** b
    return (Sar / a) ** (1 / b)
